History phase(0);
leapplus1_val = abs(in1) + 1.0;
step = 1.0 / leapplus1_val;
phase = wrap(phase + step, 0.0, 1.0);
out1 = phase;
out2 = step;
out3 = leapplus1_val;

// core polarize/fold/limiter chain for one audio channel
gateterm = in2 * in3;       // extended_gate * ampMinus1
onepgt = gateterm + 1.0;    // live gain multiplier (1 = no effect, swings during a Leap hit)
polarized = in1 * onepgt;   // gate-driven polarize stage

// Skew: asymmetric gain on polarized's own sign (BEFORE Asymmetry's contribution,
// so the two are fully independent -- Skew never affects, and is never affected
// by, what Asymmetry does at the exact-zero-crossing case)
skewFrac = in7 * 0.01;      // -100..100 -> -1..1
posGain = 1 + skewFrac;
negGain = 1 - skewFrac;
skewedPolarized = (polarized > 0) ? (polarized * posGain) : (polarized * negGain);

voidFrac = -0.01 * in6;     // Asymmetry%: 0->0, 100->-1 (matches original's fold(0) bug), 200->-2, -100->+1
signVal = (skewedPolarized > 0) ? 1 : ((skewedPolarized < 0) ? -1 : voidFrac);
term1 = skewedPolarized * in4;  // * (1-2t) -- Implosion fold blend, polarized side
term2 = signVal * in5;          // * t (smoothed) -- Implosion fold blend, folded side
finalVal = term1 + term2;

clipped = clip(finalVal, -1, 1);  // safety limiter -- always active, catches any overshoot

out1 = clipped;
out2 = skewedPolarized;
out3 = signVal;
out4 = finalVal;
out5 = onepgt;

